// === Expandir lista de URLs y aplicar reglas parametrizables ===
const P = $json || {};
const urls = Array.isArray(P.monitor_urls) ? P.monitor_urls : (Array.isArray(P.dns_urls) ? P.dns_urls : []);
const defaultOkCodes = Array.isArray(P.default_ok_http_codes) ? P.default_ok_http_codes.map(Number) : [200, 201, 202, 204, 301, 302, 303, 307, 308, 401, 403, 404];
const rules = P.url_rules || {};

function canonicalUrl(raw) {
  let s = String(raw || '').trim();
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) s = `https://${s}`;

  const m = s.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);
  if (!m) return s.toLowerCase();

  const scheme = String(m[1] || '').toLowerCase();
  const hostname = String(m[2] || '').toLowerCase();
  const explicitPort = m[3] ? `:${Number(m[3])}` : '';
  const pathname = m[4] || '/';
  const search = m[5] || '';
  const hash = m[6] || '';
  return `${scheme}://${hostname}${explicitPort}${pathname}${search}${hash}`.toLowerCase();
}

const disabledUrls = new Set(
  (Array.isArray(P.disabled_urls) ? P.disabled_urls : [])
    .map(canonicalUrl)
    .filter(Boolean)
);

function pickRule(raw, normalizedUrl, scheme, hostname) {
  const keys = [
    String(raw || '').trim(),
    normalizedUrl,
    canonicalUrl(raw),
    canonicalUrl(normalizedUrl),
    `${scheme}://${hostname}/`,
    hostname,
  ];
  for (const k of keys) {
    if (k && rules[k]) return rules[k];
  }
  return {};
}

function normalizeUrl(raw) {
  let s = String(raw || '').trim();
  if (!s) return null;

  if (!/^https?:\/\//i.test(s)) {
    s = `https://${s}`;
  }

  const m = s.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);

  if (!m) {
    return {
      original_url: String(raw || '').trim(),
      url: s,
      scheme: null,
      hostname: null,
      port: null,
      path: null,
      availability_key: `invalid::${s}`,
      parse_error: 'Formato de URL no soportado o inválido',
      retries: Number(P.alert_after_failed_attempts || 5),
      retry_delay_seconds: Number(P.retry_delay_seconds || 5),
      timeout_seconds: Number(P.timeout_seconds || 20),
      connect_timeout_seconds: Number(P.connect_timeout_seconds || 10),
      timeout_extra_retries_on_curl_28: Number(P.timeout_extra_retries_on_curl_28 || 0),
      timeout_extra_retry_delay_seconds: Number(P.timeout_extra_retry_delay_seconds || 5),
      follow_redirects: P.follow_redirects !== false,
      ignore_ssl_errors: P.ignore_ssl_errors !== false,
      ok_http_codes: defaultOkCodes,
      http_method: 'GET',
      post_body_b64: '',
      body_must_not_contain: '',
      body_must_contain_any: '',
    };
  }

  const scheme = String(m[1] || '').toLowerCase();
  const hostname = String(m[2] || '').toLowerCase();
  const explicitPort = m[3] ? Number(m[3]) : null;
  const port = explicitPort || (scheme === 'https' ? 443 : 80);
  const pathname = m[4] || '/';
  const search = m[5] || '';
  const hash = m[6] || '';
  const path = `${pathname}${search}${hash}`;
  const normalizedUrl = `${scheme}://${hostname}${explicitPort ? `:${explicitPort}` : ''}${path}`;

  const exactRule = pickRule(raw, normalizedUrl, scheme, hostname);
  const okCodes = Array.isArray(exactRule.ok_http_codes) ? exactRule.ok_http_codes.map(Number) : defaultOkCodes;
  const postBody = exactRule.post_body ? String(exactRule.post_body) : '';
  const bodyMustNot = Array.isArray(exactRule.body_must_not_contain)
    ? exactRule.body_must_not_contain.join('|')
    : String(exactRule.body_must_not_contain || '');
  const bodyMustAny = Array.isArray(exactRule.body_must_contain_any)
    ? exactRule.body_must_contain_any.join('|')
    : String(exactRule.body_must_contain_any || '');

  return {
    original_url: String(raw || '').trim(),
    url: normalizedUrl,
    scheme,
    hostname,
    port,
    path,
    check_target: `${hostname}:${port}`,
    availability_key: `${scheme}://${hostname}:${port}${path}`,
    retries: Number(exactRule.retries || P.alert_after_failed_attempts || 5),
    retry_delay_seconds: Number(exactRule.retry_delay_seconds || P.retry_delay_seconds || 5),
    timeout_seconds: Number(exactRule.timeout_seconds || P.timeout_seconds || 20),
    connect_timeout_seconds: Number(exactRule.connect_timeout_seconds || P.connect_timeout_seconds || 10),
    timeout_extra_retries_on_curl_28: Number(exactRule.timeout_extra_retries_on_curl_28 ?? P.timeout_extra_retries_on_curl_28 ?? 0),
    timeout_extra_retry_delay_seconds: Number(exactRule.timeout_extra_retry_delay_seconds ?? P.timeout_extra_retry_delay_seconds ?? 5),
    follow_redirects: exactRule.follow_redirects !== undefined ? !!exactRule.follow_redirects : P.follow_redirects !== false,
    ignore_ssl_errors: exactRule.ignore_ssl_errors !== undefined ? !!exactRule.ignore_ssl_errors : P.ignore_ssl_errors !== false,
    ok_http_codes: okCodes,
    http_method: String(exactRule.http_method || 'GET').toUpperCase(),
    post_body_b64: postBody ? Buffer.from(postBody, 'utf8').toString('base64') : '',
    body_must_not_contain: bodyMustNot,
    body_must_contain_any: bodyMustAny,
  };
}

return urls
  .filter(u => !disabledUrls.has(canonicalUrl(u)))
  .map(normalizeUrl)
  .filter(Boolean)
  .map(row => ({ json: row }));

// === Parsear resultado de curl y clasificar disponibilidad ===
const P = $item(0).$node["Set - Params"].json || {};
const originalItems = $items("Function – Expand URLs");

function parseAttemptLine(line) {
  const obj = {};
  for (const part of String(line || '').split('|')) {
    const idx = part.indexOf('=');
    if (idx < 0) continue;
    const key = part.slice(0, idx).trim();
    const value = part.slice(idx + 1).trim();
    obj[key] = value;
  }
  return obj;
}

function parseStdout(raw) {
  const txt = String(raw || '');
  const lines = txt.split(/\r?\n/).filter(Boolean);
  const attempts = [];

  for (const line of lines) {
    if (line.startsWith('ATTEMPT=')) {
      const p = parseAttemptLine(line);
      attempts.push({
        attempt: Number(p.ATTEMPT || 0),
        base_attempt: p.BASE_ATTEMPT ? Number(p.BASE_ATTEMPT) : null,
        timeout_extra_used: p.TIMEOUT_EXTRA_USED ? Number(p.TIMEOUT_EXTRA_USED) : 0,
        rc: Number(p.RC || 0),
        http_code: Number(p.HTTP_CODE || 0),
        time_total: p.TIME_TOTAL ? Number(p.TIME_TOTAL) : null,
        url_effective: p.URL_EFFECTIVE || null,
        remote_ip: p.REMOTE_IP || null,
        ssl_verify_result: p.SSL_VERIFY_RESULT || null,
        error: p.ERROR || p.CURL_ERROR || null,
        curl_error: p.CURL_ERROR || null,
        body_check: p.BODY_CHECK || null,
        body_snippet: p.BODY_SNIPPET || null
      });
    }
  }

  if (!attempts.length && txt.includes('STATUS=INVALID_URL')) {
    return { invalid: true, attempts };
  }

  return { invalid: false, attempts };
}

return $input.all().map((item, index) => {
  const src = item.json || {};
  const original = originalItems[index]?.json || {};

  const parsed = parseStdout(src.stdout || src.data || src.output || '');

  const okCodes = Array.isArray(original.ok_http_codes)
    ? original.ok_http_codes.map(Number)
    : Array.isArray(src.ok_http_codes)
      ? src.ok_http_codes.map(Number)
      : Array.isArray(P.default_ok_http_codes)
        ? P.default_ok_http_codes.map(Number)
        : [200, 201, 202, 204, 301, 302, 303, 307, 308, 401, 403, 404];

  const attempts = parsed.attempts || [];
  const successfulAttempts = attempts.filter(a =>
    a.rc === 0 &&
    okCodes.includes(Number(a.http_code)) &&
    (!a.body_check || a.body_check === 'PASS')
  );

  const lastAttempt = attempts.length ? attempts[attempts.length - 1] : null;
  const bestAttempt = successfulAttempts.length ? successfulAttempts[0] : null;

  let state = 'OK';
  let severity = 'info';
  let reason = 'URL disponible.';

  const final_http_code = bestAttempt?.http_code ?? lastAttempt?.http_code ?? null;
  const final_time_total = bestAttempt?.time_total ?? lastAttempt?.time_total ?? null;
  const final_url_effective = bestAttempt?.url_effective ?? lastAttempt?.url_effective ?? null;
  const final_remote_ip = bestAttempt?.remote_ip ?? lastAttempt?.remote_ip ?? null;
  const last_error = lastAttempt?.curl_error || lastAttempt?.error || null;

  if (parsed.invalid || original.parse_error || src.parse_error) {
    state = 'ALERT';
    severity = 'high';
    reason = original.parse_error || src.parse_error || 'Formato de URL inválido.';
  } else if (!attempts.length) {
    state = 'ALERT';
    severity = 'high';
    reason = 'No se obtuvo respuesta de curl.';
  } else if (successfulAttempts.length > 0) {
    state = 'OK';
    severity = 'info';
    reason = `URL disponible. Código HTTP permitido: ${bestAttempt.http_code}.`;
  } else if (attempts.some(a => a.rc === 0 && okCodes.includes(Number(a.http_code)) && a.body_check === 'FAIL')) {
    state = 'ALERT';
    severity = 'high';
    const bad = attempts.filter(a => a.body_check === 'FAIL').pop();
    reason = `HTTP ${bad?.http_code || 'N/D'} recibido, pero el cuerpo indica error de aplicación${bad?.body_snippet ? ': ' + bad.body_snippet : ''}.`;
  } else {
    state = 'ALERT';
    severity = 'high';

    const codes = [...new Set(
      attempts.map(a => Number(a.http_code || 0)).filter(Boolean)
    )];

    const rcs = [...new Set(
      attempts.map(a => Number(a.rc || 0))
    )];

    if (codes.length) {
      reason = `La URL no respondió con códigos permitidos después de ${attempts.length} intento(s). Códigos recibidos: ${codes.join(', ')}.`;
    } else if (last_error) {
      reason = `La URL falló después de ${attempts.length} intento(s). Último error: ${last_error}.`;
    } else {
      reason = `La URL falló después de ${attempts.length} intento(s). RC: ${rcs.join(', ')}.`;
    }
  }

  return {
    json: {
      url: original.url || src.url || src.original_url || final_url_effective || null,
      original_url: original.original_url || original.url || src.original_url || src.url || null,
      hostname: original.hostname || src.hostname || null,
      port: original.port ?? src.port ?? null,
      scheme: original.scheme || src.scheme || null,
      path: original.path || src.path || null,
      availability_key:
        original.availability_key ||
        original.url ||
        src.availability_key ||
        src.url ||
        `${original.hostname || src.hostname || 'unknown'}:${original.port || src.port || 'unknown'}`,

      state,
      severity,
      reason,
      ok_http_codes: okCodes,
      attempts,
      attempts_total: attempts.length,
      successful_attempts: successfulAttempts.length,
      final_http_code,
      final_time_total,
      final_url_effective,
      final_remote_ip,
      last_error,
      body_check: lastAttempt?.body_check || null,
      body_snippet: lastAttempt?.body_snippet || null,
      retries_configured: Number(original.retries || src.retries || P.alert_after_failed_attempts || 5),
      timeout_seconds: Number(original.timeout_seconds || src.timeout_seconds || P.timeout_seconds || 20),
      timeout_extra_retries_on_curl_28: Number(original.timeout_extra_retries_on_curl_28 ?? src.timeout_extra_retries_on_curl_28 ?? P.timeout_extra_retries_on_curl_28 ?? 0),
      timeout_extra_retry_delay_seconds: Number(original.timeout_extra_retry_delay_seconds ?? src.timeout_extra_retry_delay_seconds ?? P.timeout_extra_retry_delay_seconds ?? 5),
      checked_at_utc: new Date().toISOString()
    }
  };
});

// === Estado global + recovery parcial/total por URL ===
const P = $item(0).$node["Set - Params"].json || {};
const rows = $items("Function – Parse URL health result").map(i => i.json);

const isAlert = (r) => String(r.state || '').toUpperCase() === 'ALERT';
const alerts = rows.filter(isAlert);
const oks = rows.filter(r => String(r.state || '').toUpperCase() === 'OK');
const infos = rows.filter(r => String(r.state || '').toUpperCase() === 'INFO');

const staticData = $getWorkflowStaticData('global');
const last_state = staticData.last_state || 'INIT';
const state = alerts.length > 0 ? 'ALERT' : 'OK';
staticData.last_state = state;

const send_alert = alerts.length > 0;
const send_recovery_global = (last_state === 'ALERT' && state === 'OK');

staticData.items = staticData.items || {};
staticData.recovered = staticData.recovered || {};

const prevItems = staticData.items;
const recoveredMap = staticData.recovered;

const getKey = (r) => r.availability_key || r.url || `${r.hostname}:${r.port}`;
const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;
  currentAlertSet[k] = true;
  prevItems[k] = r;
  if (recoveredMap[k]) delete recoveredMap[k];
}

const recovered_items = [];
for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    if (!recoveredMap[k]) {
      recovered_items.push({
        ...lastRow,
        _recovery: true,
        recovered_at_utc: new Date().toISOString(),
      });
      recoveredMap[k] = 1;
    }
    delete prevItems[k];
  }
}

const send_recovery_partial = recovered_items.length > 0;
const ts_utc = new Date().toISOString();

return [{
  json: {
    workflow_name: P.workflow_name || 'Monitoreo Disponibilidad URLs HTTP',
    ts_utc,
    state,
    last_state,
    transition: `${last_state}->${state}`,
    total: rows.length,
    alert_count: alerts.length,
    total_ok: oks.length,
    total_info: infos.length,
    alerts,
    oks,
    infos,
    recovered_items,
    send_alert,
    send_recovery_global,
    send_recovery_partial,
    alert_after_failed_attempts: Number(P.alert_after_failed_attempts || 5),
    timeout_seconds: Number(P.timeout_seconds || 20),
    default_ok_http_codes: Array.isArray(P.default_ok_http_codes) ? P.default_ok_http_codes : []
  }
}];

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}
function messageCardToText(card) {
  if (!card) return "N/D";
  const lines = [];
  if (card.title) lines.push(String(card.title));
  if (card.summary && card.summary !== card.title) lines.push(String(card.summary));
  for (const sec of (card.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ""));
    if (sec.activitySubtitle) lines.push(String(sec.activitySubtitle));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push("- **" + (f.name || f.title) + ":** " + f.value);
    }
  }
  return lines.join("\n").trim();
}

// === Payload Teams ALERTA DISPONIBILIDAD ===
const P = $item(0).$node["Set - Params"].json || {};
const j = $json;
const alerts = j.alerts || [];

if (!alerts.length) return [];

function fmtSeconds(v) {
  if (v === null || v === undefined || Number.isNaN(Number(v))) return 'N/D';
  return `${Number(v).toFixed(2)}s`;
}

const title = `${P.title_prefix || 'ALERTA DISPONIBILIDAD URLs HTTP'} • ${alerts.length} URL(s)`;
const separator = '\n\n────────────────────\n\n';

const lines = alerts.map(r => {
  const codes = Array.isArray(r.attempts)
    ? r.attempts.map(a => a.http_code || 0).join(', ')
    : 'N/D';

  return [
    `• **URL:** ${r.url || 'N/D'}`,
    `  • **Host:** ${r.hostname || 'N/D'}:${r.port || '-'}`,
    `  • **Motivo:** ${r.reason || r.state || 'N/D'}`,
    `  • **Intentos:** ${r.attempts_total || 0}/${r.retries_configured || P.alert_after_failed_attempts || 5}`,
    `  • **HTTP recibidos:** ${codes}`,
    `  • **Último HTTP:** ${r.final_http_code ?? 'N/D'}`,
    `  • **Tiempo último/mejor:** ${fmtSeconds(r.final_time_total)}`,
    `  • **IP remota:** ${r.final_remote_ip || 'N/D'}`,
    `  • **URL efectiva:** ${r.final_url_effective || 'N/D'}`,
    `  • **Último error:** ${r.last_error || 'N/D'}`
  ].join('\n');
}).join(separator);

return [{ json: { body: toAdaptiveCardBody(messageCardToText({
      "@type": "MessageCard",
      "@context": "https://schema.org/extensions",
      themeColor: "C0392B",
      summary: title,
      title,
      sections: [
        {
          markdown: true,
          text:
            `🔴 **Alerta de disponibilidad de Sites**\n` +
            `Reintentos configurados: **${P.alert_after_failed_attempts || 5}**\n` +
            `Timeout por intento: **${P.timeout_seconds || 20}s**\n` +
            `Reintentos solo si falla (curl 6/7/28/56): **${P.alert_after_failed_attempts || 3}** cada **${P.retry_delay_seconds || 5}s**\n` +
            `Códigos OK por defecto: **${(P.default_ok_http_codes || []).join(', ')}**\n` +
            `URLs evaluadas: **${j.total || 0}**\n` +
            `En alerta: **${j.alert_count || 0}**\n` +
            `Hora UTC: ${j.ts_utc || new Date().toISOString()}`
        },
        {
          markdown: true,
          text: `📄 **Detalle**\n\n${lines}`
        }
      ]
    }
  )) } }];

function toAdaptiveCardBody(message) {
  return {
    type: "AdaptiveCard",
    $schema: "http://adaptivecards.io/schemas/adaptive-card.json",
    version: "1.5",
    body: [{ type: "TextBlock", text: String(message ?? "N/D"), wrap: true }]
  };
}
function messageCardToText(card) {
  if (!card) return "N/D";
  const lines = [];
  if (card.title) lines.push(String(card.title));
  if (card.summary && card.summary !== card.title) lines.push(String(card.summary));
  for (const sec of (card.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ""));
    if (sec.activitySubtitle) lines.push(String(sec.activitySubtitle));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push("- **" + (f.name || f.title) + ":** " + f.value);
    }
  }
  return lines.join("\n").trim();
}

// === Payload Teams RECOVERY DISPONIBILIDAD ===
const j = $json;
const recovered = j.recovered_items || [];
const stillAlerts = j.alerts || [];

if (!recovered.length && !j.send_recovery_global) return [];

const global = !!j.send_recovery_global;
const title = global
  ? 'RECOVERY TOTAL – Disponibilidad de Sites'
  : 'RECOVERY PARCIAL – Disponibilidad de Sites';

function fmtSeconds(v) {
  if (v === null || v === undefined || Number.isNaN(Number(v))) return 'N/D';
  return `${Number(v).toFixed(2)}s`;
}

const separator = '\n\n────────────────────\n\n';

const recoveredLines = recovered.length
  ? recovered.map(r => {
      return [
        `• **URL:** ${r.url || 'N/D'}`,
        `  • Host: ${r.hostname || '-'}:${r.port || '-'}`,
        `  • Último HTTP registrado cuando fallaba: ${r.final_http_code ?? 'N/D'}`,
        `  • Tiempo registrado: ${fmtSeconds(r.final_time_total)}`,
        `  • Recuperado UTC: ${r.recovered_at_utc || j.ts_utc}`
      ].join('\n');
    }).join(separator)
  : (global
      ? '- Todas las URLs que estaban en alerta se recuperaron.'
      : '- Sin elementos recuperados individuales.');

const pendingLines = stillAlerts.length
  ? stillAlerts.map(r =>
      `• **URL:** ${r.url || 'N/D'} • ${r.reason || r.state || 'N/D'} • último HTTP: **${r.final_http_code ?? 'N/D'}**`
    ).join(separator)
  : '- No quedan URLs en alerta.';

const intro = global
  ? '🟢 **Recovery total:** todas las URLs que venían en alerta ya responden nuevamente.'
  : '🟡 **Recovery parcial:** algunas URLs se recuperaron, pero todavía quedan otras pendientes.';

return [{ json: { body: toAdaptiveCardBody(messageCardToText({
    "@type": "MessageCard",
    "@context": "https://schema.org/extensions",
    themeColor: global ? "2E8B57" : "F39C12",
    summary: title,
    title,
    sections: [
      {
        markdown: true,
        text:
          `${intro}\n\n` +
          `Hora UTC: ${j.ts_utc}\n` +
          `Recuperadas: **${recovered.length}**\n` +
          `Aún en alerta: **${stillAlerts.length}**`
      },
      {
        markdown: true,
        text: `✅ **Recuperadas**\n\n${recoveredLines}`
      },
      {
        markdown: true,
        text: `📌 **Aún en alerta**\n\n${pendingLines}`
      }
    ]
  }
)) } }];

// === Expandir lista de URLs y aplicar reglas parametrizables ===
const P = $json || {};
const urls = Array.isArray(P.monitor_urls) ? P.monitor_urls : (Array.isArray(P.dns_urls) ? P.dns_urls : []);
const defaultOkCodes = Array.isArray(P.default_ok_http_codes) ? P.default_ok_http_codes.map(Number) : [200, 201, 202, 204, 301, 302, 303, 307, 308, 401, 403, 404];
const rules = P.url_rules || {};

function canonicalUrl(raw) {
  let s = String(raw || '').trim();
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) s = `https://${s}`;

  const m = s.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);
  if (!m) return s.toLowerCase();

  const scheme = String(m[1] || '').toLowerCase();
  const hostname = String(m[2] || '').toLowerCase();
  const explicitPort = m[3] ? `:${Number(m[3])}` : '';
  const pathname = m[4] || '/';
  const search = m[5] || '';
  const hash = m[6] || '';
  return `${scheme}://${hostname}${explicitPort}${pathname}${search}${hash}`.toLowerCase();
}

const disabledUrls = new Set(
  (Array.isArray(P.disabled_urls) ? P.disabled_urls : [])
    .map(canonicalUrl)
    .filter(Boolean)
);

function pickRule(raw, normalizedUrl, scheme, hostname) {
  const keys = [
    String(raw || '').trim(),
    normalizedUrl,
    canonicalUrl(raw),
    canonicalUrl(normalizedUrl),
    `${scheme}://${hostname}/`,
    hostname,
  ];
  for (const k of keys) {
    if (k && rules[k]) return rules[k];
  }
  return {};
}

function normalizeUrl(raw) {
  let s = String(raw || '').trim();
  if (!s) return null;

  if (!/^https?:\/\//i.test(s)) {
    s = `https://${s}`;
  }

  const m = s.match(/^(https?):\/\/([^\/:?#]+)(?::(\d+))?(\/[^?#]*)?(\?[^#]*)?(#.*)?$/i);

  if (!m) {
    return {
      original_url: String(raw || '').trim(),
      url: s,
      scheme: null,
      hostname: null,
      port: null,
      path: null,
      availability_key: `invalid::${s}`,
      parse_error: 'Formato de URL no soportado o inválido',
      retries: Number(P.alert_after_failed_attempts || 5),
      retry_delay_seconds: Number(P.retry_delay_seconds || 5),
      timeout_seconds: Number(P.timeout_seconds || 20),
      connect_timeout_seconds: Number(P.connect_timeout_seconds || 10),
      timeout_extra_retries_on_curl_28: Number(P.timeout_extra_retries_on_curl_28 || 0),
      timeout_extra_retry_delay_seconds: Number(P.timeout_extra_retry_delay_seconds || 5),
      follow_redirects: P.follow_redirects !== false,
      ignore_ssl_errors: P.ignore_ssl_errors !== false,
      ok_http_codes: defaultOkCodes,
      http_method: 'GET',
      post_body_b64: '',
      body_must_not_contain: '',
      body_must_contain_any: '',
    };
  }

  const scheme = String(m[1] || '').toLowerCase();
  const hostname = String(m[2] || '').toLowerCase();
  const explicitPort = m[3] ? Number(m[3]) : null;
  const port = explicitPort || (scheme === 'https' ? 443 : 80);
  const pathname = m[4] || '/';
  const search = m[5] || '';
  const hash = m[6] || '';
  const path = `${pathname}${search}${hash}`;
  const normalizedUrl = `${scheme}://${hostname}${explicitPort ? `:${explicitPort}` : ''}${path}`;

  const exactRule = pickRule(raw, normalizedUrl, scheme, hostname);
  const okCodes = Array.isArray(exactRule.ok_http_codes) ? exactRule.ok_http_codes.map(Number) : defaultOkCodes;
  const postBody = exactRule.post_body ? String(exactRule.post_body) : '';
  const bodyMustNot = Array.isArray(exactRule.body_must_not_contain)
    ? exactRule.body_must_not_contain.join('|')
    : String(exactRule.body_must_not_contain || '');
  const bodyMustAny = Array.isArray(exactRule.body_must_contain_any)
    ? exactRule.body_must_contain_any.join('|')
    : String(exactRule.body_must_contain_any || '');

  return {
    original_url: String(raw || '').trim(),
    url: normalizedUrl,
    scheme,
    hostname,
    port,
    path,
    check_target: `${hostname}:${port}`,
    availability_key: `${scheme}://${hostname}:${port}${path}`,
    retries: Number(exactRule.retries || P.alert_after_failed_attempts || 5),
    retry_delay_seconds: Number(exactRule.retry_delay_seconds || P.retry_delay_seconds || 5),
    timeout_seconds: Number(exactRule.timeout_seconds || P.timeout_seconds || 20),
    connect_timeout_seconds: Number(exactRule.connect_timeout_seconds || P.connect_timeout_seconds || 10),
    timeout_extra_retries_on_curl_28: Number(exactRule.timeout_extra_retries_on_curl_28 ?? P.timeout_extra_retries_on_curl_28 ?? 0),
    timeout_extra_retry_delay_seconds: Number(exactRule.timeout_extra_retry_delay_seconds ?? P.timeout_extra_retry_delay_seconds ?? 5),
    follow_redirects: exactRule.follow_redirects !== undefined ? !!exactRule.follow_redirects : P.follow_redirects !== false,
    ignore_ssl_errors: exactRule.ignore_ssl_errors !== undefined ? !!exactRule.ignore_ssl_errors : P.ignore_ssl_errors !== false,
    ok_http_codes: okCodes,
    http_method: String(exactRule.http_method || 'GET').toUpperCase(),
    post_body_b64: postBody ? Buffer.from(postBody, 'utf8').toString('base64') : '',
    body_must_not_contain: bodyMustNot,
    body_must_contain_any: bodyMustAny,
  };
}

