const P = $item(0).$node["Set - Params"].json || {};
const rows = $items("Function – Parse URL health result").map(i => i.json);

const isAlert = (r) => String(r.state || '').toUpperCase() === 'ALERT';
const alerts = rows.filter(isAlert);
const oks = rows.filter(r => String(r.state || '').toUpperCase() === 'OK');
const infos = rows.filter(r => String(r.state || '').toUpperCase() === 'INFO');

const staticData = $getWorkflowStaticData('global');
const last_state = staticData.last_state || 'INIT';
const state = alerts.length > 0 ? 'ALERT' : 'OK';
staticData.last_state = state;

const send_alert = alerts.length > 0;
const send_recovery_global = (last_state === 'ALERT' && state === 'OK');

staticData.items = staticData.items || {};
staticData.recovered = staticData.recovered || {};

const prevItems = staticData.items;
const recoveredMap = staticData.recovered;

const getKey = (r) => r.availability_key || r.url || `${r.hostname}:${r.port}`;
const currentAlertSet = {};

for (const r of alerts) {
  const k = getKey(r);
  if (!k) continue;
  currentAlertSet[k] = true;
  prevItems[k] = r;
  if (recoveredMap[k]) delete recoveredMap[k];
}

const recovered_items = [];
for (const [k, lastRow] of Object.entries(prevItems)) {
  if (!currentAlertSet[k]) {
    if (!recoveredMap[k]) {
      recovered_items.push({
        ...lastRow,
        _recovery: true,
        recovered_at_utc: new Date().toISOString(),
      });
      recoveredMap[k] = 1;
    }
    delete prevItems[k];
  }
}

const send_recovery_partial = recovered_items.length > 0;
const ts_utc = new Date().toISOString();

return [{
  json: {
    workflow_name: P.workflow_name || 'Monitoreo Disponibilidad URLs HTTP',
    ts_utc,
    state,
    last_state,
    transition: `${last_state}->${state}`,
    total: rows.length,
    alert_count: alerts.length,
    total_ok: oks.length,
    total_info: infos.length,
    alerts,
    oks,
    infos,
    recovered_items,
    send_alert,
    send_recovery_global,
    send_recovery_partial,
    alert_after_failed_attempts: Number(P.alert_after_failed_attempts || 5),
    timeout_seconds: Number(P.timeout_seconds || 20),
    default_ok_http_codes: Array.isArray(P.default_ok_http_codes) ? P.default_ok_http_codes : []
  }
}];

