function messageCardToText(card) {
  if (!card) return "N/D";
  const lines = [];
  if (card.title) lines.push(String(card.title));
  if (card.summary && card.summary !== card.title) lines.push(String(card.summary));
  for (const sec of (card.sections || [])) {
    if (sec.text) lines.push(String(sec.text));
    if (sec.activityTitle) lines.push(String(sec.activityTitle).replace(/^\*\*|\*\*$/g, ""));
    if (sec.activitySubtitle) lines.push(String(sec.activitySubtitle));
    if (Array.isArray(sec.facts)) {
      for (const f of sec.facts) lines.push("- **" + (f.name || f.title) + ":** " + f.value);
    }
  }
  return lines.join("\n").trim();
}

